package thaumcraft.verification;
import java.nio.file.*;
import com.google.gson.*;
import net.minecraft.client.Minecraft;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.ClientTickEvent;
/** Dev-only native input hold and framebuffer capture. Excluded from release JARs. */
@EventBusSubscriber(modid="thaumcraft_r3_test",value=Dist.CLIENT)
public final class ClientCorrectionProbe {
 private static int age,hold,using,itemParticleTicks,maxItemParticles,essentiaParticleTicks,overlapTicks,firstItemTick,lastEssentiaTick;private static String name;private static boolean active,connected;
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){
  if(!"visual".equals(System.getProperty("thaumcraft.r3.phase")))return;var mc=Minecraft.getInstance();if(!connected&&mc.screen instanceof net.minecraft.client.gui.screens.TitleScreen){connected=true;net.minecraft.client.gui.screens.ConnectScreen.startConnecting(mc.screen,mc,net.minecraft.client.multiplayer.resolver.ServerAddress.parseString("127.0.0.1:25577"),new net.minecraft.client.multiplayer.ServerData("R3 local","127.0.0.1:25577",net.minecraft.client.multiplayer.ServerData.Type.OTHER),false,null);}
  if(mc.level==null||mc.player==null)return;
  var root=Path.of(System.getProperty("thaumcraft.r3.root"));var control=root.resolve("analysis/r3/evidence/client-probe.json");
  try{if(Files.exists(control)){var action=JsonParser.parseString(Files.readString(control)).getAsJsonObject();name=action.get("name").getAsString();if(!name.matches("[a-z0-9_-]+"))throw new IllegalArgumentException("Invalid capture name");hold=action.has("hold")?Math.clamp(action.get("hold").getAsInt(),0,200):0;age=using=itemParticleTicks=maxItemParticles=essentiaParticleTicks=overlapTicks=lastEssentiaTick=0;firstItemTick=-1;if(action.has("research")&&mc.screen instanceof thaumcraft.client.ThaumonomiconScreen book){try{var selected=book.getClass().getDeclaredField("selected");selected.setAccessible(true);selected.set(book,thaumcraft.network.ClientKnowledge.definitions().get(action.get("research").getAsString()));var spread=book.getClass().getDeclaredField("spread");spread.setAccessible(true);spread.setInt(book,action.has("spread")?action.get("spread").getAsInt():0);}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}}if(action.has("scene")){String scene=action.get("scene").getAsString();if(!java.util.List.of("altar","table","scan","charge","birth","jar").contains(scene))throw new IllegalArgumentException("Invalid scene");mc.player.connection.sendCommand("r3scene "+scene);}active=true;Files.delete(control);}}
  catch(java.io.IOException e){throw new java.io.UncheckedIOException(e);}
  if(!active)return;int[] itemParticles={0},essentiaParticles={0};mc.particleEngine.iterateParticles(p->{if(p.getClass().getName().equals("thaumcraft.client.LegacyParticles$Mote")){if(p.getRenderType()==net.minecraft.client.particle.ParticleRenderType.TERRAIN_SHEET)itemParticles[0]++;try{var kind=p.getClass().getDeclaredField("kind");kind.setAccessible(true);if(kind.getInt(p)==0)essentiaParticles[0]++;}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}}});if(essentiaParticles[0]>0){essentiaParticleTicks++;lastEssentiaTick=age;}if(itemParticles[0]>0&&firstItemTick<0)firstItemTick=age;if(itemParticles[0]>0&&essentiaParticles[0]>0)overlapTicks++;if(itemParticles[0]>0)itemParticleTicks++;maxItemParticles=Math.max(maxItemParticles,itemParticles[0]);age++;mc.options.keyUse.setDown(age<=hold);if(mc.player.isUsingItem())using++;
  if(age==15||age==40||age==80||name.startsWith("altar")&&age%5==0&&age<=300)net.minecraft.client.Screenshot.grab(mc.gameDirectory,"r3-"+name+"-"+age+".png",mc.getMainRenderTarget(),c->{});
  if(age>Math.max(hold+5,name.startsWith("altar")?300:80)){mc.options.keyUse.setDown(false);active=false;try{var output=new JsonObject();var models=new JsonObject();for(String id:java.util.List.of("arcane_stone","table","arcane_workbench","research_table")){var item=net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("thaumcraft",id));var model=mc.getItemRenderer().getModel(new net.minecraft.world.item.ItemStack(item),mc.level,mc.player,0);var transform=model.getTransforms().getTransform(net.minecraft.world.item.ItemDisplayContext.GUI);var entry=new JsonObject();entry.addProperty("gui3d",model.isGui3d());entry.addProperty("rotation",transform.rotation.toString());entry.addProperty("scale",transform.scale.toString());entry.addProperty("particle",model.getParticleIcon().contents().name().toString());models.add(id,entry);}output.add("models",models);output.addProperty("itemParticleTicks",itemParticleTicks);output.addProperty("maxItemParticles",maxItemParticles);output.addProperty("essentiaParticleTicks",essentiaParticleTicks);output.addProperty("firstItemTick",firstItemTick);output.addProperty("lastEssentiaTick",lastEssentiaTick);output.addProperty("overlapTicks",overlapTicks);output.addProperty("usingTicks",using);output.addProperty("heldItem",net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(mc.player.getMainHandItem().getItem()).toString());output.addProperty("vis",thaumcraft.api.aspects.Aspects.PRIMALS.stream().mapToInt(a->thaumcraft.items.WandVis.get(mc.player.getMainHandItem(),a)).sum());Files.writeString(root.resolve("analysis/r3/evidence/client-probe-"+name+".json"),output.toString()+"\n");}catch(java.io.IOException e){throw new java.io.UncheckedIOException(e);}}
 }
 private ClientCorrectionProbe(){}
}
